%[text] # Trabajo Práctico 1: Transformada Z - Ejercicio 3 - 4 y 5
%[text:tableOfContents]{"heading":"Table of Contents"}
%[text] ## Ejercicio 3:
%[text] - Sea $&dollar&;x\[n\]=(0.5)^nu\[n\]+(0.3)^nu\[n\]+(0.9)^nu\[n\]&dollar&;$.
%[text] - ¿Cuál es su X(z) y su ROC? \
clc
clear
close all
a1 = [1 -1/2];
a2 = [1 -0.3];
a3 = [1 -0.9];
a1_a2 = conv(a1,a2);
a1_a3 = conv(a1,a3);
a2_a3 = conv(a2, a3);
a1_a2_a3 = conv(a1_a2, a3);
b = a2_a3 + a1_a3 + a1_a2;
zplane(b,a1_a2_a3) %[output:0c10072e]
%%
%[text] ## Ejercicio 4:
%[text] ![](text:image:7d17)
%[text] Utilice la función residuez para encontrar los polos de la función. Use la función filter para representar la respuesta del sistema en el dominio del tiempo.
b4 = [1];
a4 = [1 -0.7];
[r,p,k]=residuez(b4,a4) %[output:4a31de0e] %[output:52fcc2fb] %[output:4180c8b4]
N = 20;
x_imp = [1 zeros(1,N-1)];
y_imp = filter(b4,a4,x_imp);
stem(0:N-1,y_imp) %[output:58a0ec22]
xlabel('n') %[output:58a0ec22]
ylabel('y[n]') %[output:58a0ec22]
title('Respuesta al impulso') %[output:58a0ec22]
grid on %[output:58a0ec22]
x_step = ones(1,N);
y_step = filter(b,a,x_step);
stem(0:N-1,y_imp) %[output:3c6bafa3]
xlabel('n') %[output:3c6bafa3]
ylabel('y[n]') %[output:3c6bafa3]
title('Respuesta al escalon') %[output:3c6bafa3]
grid on %[output:3c6bafa3]
%%
%[text] ### 
%[text] ## Ejercicio 5:
%[text] ![](text:image:510d)
b = [1];
a = [1 -0.5 -0.1 -0.2];
x = ones(1,40);
zi = filtic(b,a,[1 2 3]);
y = filter(b,a,x,zi);
zplane(1,[1 -0.5 -0.1 -0.2]) %[output:6929790e]
stem(0:39,y) %[output:689f3d30]
xlabel('n') %[output:689f3d30]
ylabel('y[n]') %[output:689f3d30]
title('Respuesta del sistema') %[output:689f3d30]
grid on %[output:689f3d30]
%%
